insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000001861', 'analyze', '/ˈænəlaɪz/', 'verb', 'analisar', 'Researchers analyzed the data carefully.', 'Os pesquisadores analisaram os dados cuidadosamente.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001862', 'demonstrate', '/ˈdemənstreɪt/', 'verb', 'demonstrar', 'The study demonstrates a clear connection between the two factors.', 'O estudo demonstra uma clara conexão entre os dois fatores.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001863', 'examine', '/ɪɡˈzæmɪn/', 'verb', 'examinar', 'The report examines the causes of the crisis.', 'O relatório examina as causas da crise.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001864', 'identify', '/aɪˈdentɪfaɪ/', 'verb', 'identificar', 'The team identified three main problems.', 'A equipe identificou três problemas principais.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001865', 'illustrate', '/ˈɪləstreɪt/', 'verb', 'ilustrar', 'This example illustrates the theory perfectly.', 'Este exemplo ilustra a teoria perfeitamente.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001866', 'indicate', '/ˈɪndɪkeɪt/', 'verb', 'indicar', 'The results indicate a significant improvement.', 'Os resultados indicam uma melhora significativa.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001867', 'evidence', '/ˈevɪdəns/', 'noun', 'evidência', 'There is strong evidence to support this theory.', 'Há evidências fortes que sustentam essa teoria.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001868', 'hypothesis', '/haɪˈpɑːθəsɪs/', 'noun', 'hipótese', 'The hypothesis was confirmed by the experiment.', 'A hipótese foi confirmada pelo experimento.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001869', 'argument', '/ˈɑːrɡjumənt/', 'noun', 'argumento', 'Her argument was well structured and convincing.', 'O argumento dela foi bem estruturado e convincente.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001870', 'source', '/sɔːrs/', 'noun', 'fonte', 'Always check the source before citing information.', 'Sempre verifique a fonte antes de citar uma informação.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001871', 'summary', '/ˈsʌməri/', 'noun', 'resumo', 'Write a short summary of the main findings.', 'Escreva um resumo curto das principais descobertas.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001872', 'perspective', '/pərˈspektɪv/', 'noun', 'perspectiva', 'The article presents an interesting perspective on the issue.', 'O artigo apresenta uma perspectiva interessante sobre o assunto.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001873', 'conclude', '/kənˈkluːd/', 'verb', 'concluir', 'The researchers concluded that more studies were needed.', 'Os pesquisadores concluíram que mais estudos eram necessários.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001874', 'assess', '/əˈses/', 'verb', 'avaliar', 'It is difficult to assess the real impact of the policy.', 'É difícil avaliar o impacto real da política.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001875', 'evaluate', '/ɪˈvæljueɪt/', 'verb', 'avaliar', 'Teachers evaluate students based on several criteria.', 'Professores avaliam os alunos com base em vários critérios.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001876', 'justify', '/ˈdʒʌstɪfaɪ/', 'verb', 'justificar', 'She justified her decision with solid arguments.', 'Ela justificou sua decisão com argumentos sólidos.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001877', 'outline', '/ˈaʊtlaɪn/', 'verb', 'esboçar/resumir', 'The introduction outlines the main goals of the study.', 'A introdução resume os principais objetivos do estudo.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001878', 'research', '/rɪˈsɜːrtʃ/', 'verb', 'pesquisar', 'She spent months researching the topic before writing the paper.', 'Ela passou meses pesquisando o tema antes de escrever o artigo.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001879', 'significant', '/sɪɡˈnɪfɪkənt/', 'adjective', 'significativo', 'The results showed a significant increase in performance.', 'Os resultados mostraram um aumento significativo no desempenho.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001880', 'valid', '/ˈvælɪd/', 'adjective', 'válido', 'This is a valid point that deserves further discussion.', 'Este é um ponto válido que merece mais discussão.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001881', 'consistent', '/kənˈsɪstənt/', 'adjective', 'consistente', 'The findings were consistent across all three experiments.', 'Os resultados foram consistentes em todos os três experimentos.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001882', 'objective', '/əbˈdʒektɪv/', 'adjective', 'objetivo', 'Try to remain objective when analyzing the data.', 'Tente permanecer objetivo ao analisar os dados.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001883', 'subjective', '/səbˈdʒektɪv/', 'adjective', 'subjetivo', 'Personal opinions can be quite subjective.', 'Opiniões pessoais podem ser bem subjetivas.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001884', 'substantial', '/səbˈstænʃəl/', 'adjective', 'substancial', 'There was a substantial difference between the two groups.', 'Havia uma diferença substancial entre os dois grupos.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001885', 'criteria', '/kraɪˈtɪriə/', 'noun', 'critérios', 'The committee established clear criteria for selection.', 'O comitê estabeleceu critérios claros para seleção.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001886', 'factor', '/ˈfæktər/', 'noun', 'fator', 'Motivation is an important factor in learning a language.', 'Motivação é um fator importante no aprendizado de um idioma.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001887', 'framework', '/ˈfreɪmwɜːrk/', 'noun', 'estrutura/referencial', 'The essay follows a clear theoretical framework.', 'O ensaio segue uma estrutura teórica clara.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001888', 'methodology', '/ˌmeθəˈdɑːlədʒi/', 'noun', 'metodologia', 'The methodology section explains how the data was collected.', 'A seção de metodologia explica como os dados foram coletados.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001889', 'previous', '/ˈpriːviəs/', 'adjective', 'anterior', 'This study builds on previous research in the field.', 'Este estudo se baseia em pesquisas anteriores na área.', 'B2', array['academic']),
('30000000-0000-0000-0000-000000001890', 'thorough', '/ˈθɜːroʊ/', 'adjective', 'minucioso', 'The report is based on a thorough analysis of the data.', 'O relatório se baseia em uma análise minuciosa dos dados.', 'B2', array['academic']);

