('20000000-0000-0000-0000-000000000311', 'fill_blank', 7, '{"sentence": "The report ___ the causes of the crisis.", "options": ["examines", "justifies", "outlines"], "correct": "examines", "translation": "O relatório examina as causas da crise."}'),
('20000000-0000-0000-0000-000000000311', 'fill_blank', 8, '{"sentence": "The team ___ three main problems.", "options": ["identified", "researched", "assessed"], "correct": "identified", "translation": "A equipe identificou três problemas principais."}'),
('20000000-0000-0000-0000-000000000311', 'word_order', 9, '{"words": ["The", "results", "indicate", "a", "significant", "improvement"], "correct_sentence": "The results indicate a significant improvement", "translation": "Os resultados indicam uma melhora significativa"}'),
('20000000-0000-0000-0000-000000000311', 'word_order', 10, '{"words": ["The", "study", "demonstrates", "a", "clear", "connection", "between", "the", "two", "factors"], "correct_sentence": "The study demonstrates a clear connection between the two factors", "translation": "O estudo demonstra uma clara conexão entre os dois fatores"}'),
('20000000-0000-0000-0000-000000000311', 'reading', 11, '{"passage": "Academic writing relies on precise verbs to describe research actions. Researchers analyze data, examine causes, and identify patterns. A good example can illustrate a theory clearly, while results often indicate whether a hypothesis is correct or not. These verbs help writers sound objective and precise.", "translation": "A escrita acadêmica depende de verbos precisos para descrever ações de pesquisa. Pesquisadores analyze dados, examine causas, e identify padrões. Um bom exemplo pode illustrate uma teoria com clareza, enquanto resultados costumam indicate se uma hipótese está correta ou não. Esses verbos ajudam os autores a soar objetivos e precisos.", "question": "What do results often indicate, according to the text?", "options": ["Whether a hypothesis is correct", "The author''s opinion", "The methodology used"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000311', 'listening', 12, '{"audio_text": "Researchers analyzed the data carefully. The team identified three main problems. This example illustrates the theory perfectly.", "question": "How many problems did the team identify, according to the audio?", "options": ["Two", "Three", "Four"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000311', 'dictation', 13, '{"audio_text": "Researchers analyzed the data carefully.", "expected": "Researchers analyzed the data carefully."}'),
('20000000-0000-0000-0000-000000000311', 'typing', 14, '{"prompt_pt": "Traduza: ''O estudo examina os dados e identifica padrões importantes.''", "expected": "The study examines the data and identifies important patterns.", "ai_review": true}'),

