('20000000-0000-0000-0000-000000000312', 'matching', 6, '{"pairs": [{"left": "evidence", "right": "evidência"}, {"left": "hypothesis", "right": "hipótese"}, {"left": "argument", "right": "argumento"}, {"left": "source", "right": "fonte"}, {"left": "summary", "right": "resumo"}, {"left": "perspective", "right": "perspectiva"}]}'),
('20000000-0000-0000-0000-000000000312', 'fill_blank', 7, '{"sentence": "The ___ was confirmed by the experiment.", "options": ["hypothesis", "summary", "framework"], "correct": "hypothesis", "translation": "A hipótese foi confirmada pelo experimento."}'),
('20000000-0000-0000-0000-000000000312', 'fill_blank', 8, '{"sentence": "Always check the ___ before citing information.", "options": ["source", "argument", "criteria"], "correct": "source", "translation": "Sempre verifique a fonte antes de citar uma informação."}'),
('20000000-0000-0000-0000-000000000312', 'word_order', 9, '{"words": ["Her", "argument", "was", "well", "structured", "and", "convincing"], "correct_sentence": "Her argument was well structured and convincing", "translation": "O argumento dela foi bem estruturado e convincente"}'),
('20000000-0000-0000-0000-000000000312', 'word_order', 10, '{"words": ["Write", "a", "short", "summary", "of", "the", "main", "findings"], "correct_sentence": "Write a short summary of the main findings", "translation": "Escreva um resumo curto das principais descobertas"}'),
('20000000-0000-0000-0000-000000000312', 'reading', 11, '{"passage": "A strong academic essay presents clear evidence to support its argument, tests a hypothesis, and cites reliable sources. At the end, a good summary highlights the main points, and the writer may offer a personal perspective on the topic, as long as it is backed by facts.", "translation": "Um bom ensaio acadêmico apresenta evidence clara para sustentar seu argument, testa uma hypothesis, e cita source confiáveis. No final, um bom summary destaca os pontos principais, e o autor pode oferecer uma perspective pessoal sobre o tema, desde que seja apoiada por fatos.", "question": "What does a good summary do, according to the text?", "options": ["It introduces the topic", "It highlights the main points", "It cites sources"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000312', 'listening', 12, '{"audio_text": "There is strong evidence to support this theory. Her argument was well structured and convincing. Always check the source before citing information.", "question": "What was well structured and convincing, according to the audio?", "options": ["The evidence", "Her argument", "The source"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000312', 'dictation', 13, '{"audio_text": "There is strong evidence to support this theory.", "expected": "There is strong evidence to support this theory."}'),
('20000000-0000-0000-0000-000000000312', 'typing', 14, '{"prompt_pt": "Traduza: ''O argumento dela se baseia em evidências de fontes confiáveis.''", "expected": "Her argument is based on evidence from reliable sources.", "ai_review": true}'),

-- Lição 313: Verbos de avaliação e conclusão (conclude, assess, evaluate, justify, outline, research)
('20000000-0000-0000-0000-000000000313', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001873", "show_image": false}'),
('20000000-0000-0000-0000-000000000313', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001875", "show_image": false}'),
('20000000-0000-0000-0000-000000000313', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001878", "show_image": false}'),
('20000000-0000-0000-0000-000000000313', 'multiple_choice', 4, '{"question": "The researchers ___ that more studies were needed.", "audio_text": null, "options": ["concluded", "outlined", "assessed"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000313', 'multiple_choice', 5, '{"question": "She ___ her decision with solid arguments.", "audio_text": null, "options": ["justified", "researched", "evaluated"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000313', 'matching', 6, '{"pairs": [{"left": "conclude", "right": "concluir"}, {"left": "assess", "right": "avaliar"}, {"left": "evaluate", "right": "avaliar"}, {"left": "justify", "right": "justificar"}, {"left": "outline", "right": "esboçar/resumir"}, {"left": "research", "right": "pesquisar"}]}'),
('20000000-0000-0000-0000-000000000313', 'fill_blank', 7, '{"sentence": "Teachers ___ students based on several criteria.", "options": ["evaluate", "conclude", "outline"], "correct": "evaluate", "translation": "Professores avaliam os alunos com base em vários critérios."}'),
('20000000-0000-0000-0000-000000000313', 'fill_blank', 8, '{"sentence": "The introduction ___ the main goals of the study.", "options": ["outlines", "assesses", "justifies"], "correct": "outlines", "translation": "A introdução resume os principais objetivos do estudo."}'),
('20000000-0000-0000-0000-000000000313', 'word_order', 9, '{"words": ["It", "is", "difficult", "to", "assess", "the", "real", "impact", "of", "the", "policy"], "correct_sentence": "It is difficult to assess the real impact of the policy", "translation": "É difícil avaliar o impacto real da política"}'),
('20000000-0000-0000-0000-000000000313', 'word_order', 10, '{"words": ["She", "spent", "months", "researching", "the", "topic", "before", "writing", "the", "paper"], "correct_sentence": "She spent months researching the topic before writing the paper", "translation": "Ela passou meses pesquisando o tema antes de escrever o artigo"}'),
('20000000-0000-0000-0000-000000000313', 'reading', 11, '{"passage": "Writing a good academic paper involves several stages. First, the author must research the topic thoroughly. Then, the introduction usually outlines the main goals, and the body of the text works to justify each claim. At the end, the writer must assess the results and conclude with a clear final statement.", "translation": "Escrever um bom artigo acadêmico envolve várias etapas. Primeiro, o autor precisa research o tema minuciosamente. Depois, a introdução geralmente outlines os objetivos principais, e o corpo do texto trabalha para justify cada afirmação. No final, o autor precisa assess os resultados e conclude com uma declaração final clara.", "question": "What does the introduction usually do, according to the text?", "options": ["It justifies each claim", "It outlines the main goals", "It assesses the results"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000313', 'listening', 12, '{"audio_text": "The researchers concluded that more studies were needed. Teachers evaluate students based on several criteria. She justified her decision with solid arguments.", "question": "What did the researchers conclude, according to the audio?", "options": ["That the study was finished", "That more studies were needed", "That the hypothesis was wrong"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000313', 'dictation', 13, '{"audio_text": "The researchers concluded that more studies were needed.", "expected": "The researchers concluded that more studies were needed."}'),
('20000000-0000-0000-0000-000000000313', 'typing', 14, '{"prompt_pt": "Traduza: ''Ela pesquisou o tema, avaliou os resultados e concluiu que a hipótese estava correta.''", "expected": "She researched the topic, evaluated the results, and concluded that the hypothesis was correct.", "ai_review": true}'),

-- Lição 314: Adjetivos acadêmicos (significant, valid, consistent, objective, subjective, substantial)
('20000000-0000-0000-0000-000000000314', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001879", "show_image": false}'),
('20000000-0000-0000-0000-000000000314', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001881", "show_image": false}'),
('20000000-0000-0000-0000-000000000314', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001884", "show_image": false}'),
('20000000-0000-0000-0000-000000000314', 'multiple_choice', 4, '{"question": "This is a ___ point that deserves further discussion.", "audio_text": null, "options": ["valid", "subjective", "previous"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000314', 'multiple_choice', 5, '{"question": "Try to remain ___ when analyzing the data.", "audio_text": null, "options": ["objective", "significant", "consistent"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000314', 'matching', 6, '{"pairs": [{"left": "significant", "right": "significativo"}, {"left": "valid", "right": "válido"}, {"left": "consistent", "right": "consistente"}, {"left": "objective", "right": "objetivo"}, {"left": "subjective", "right": "subjetivo"}, {"left": "substantial", "right": "substancial"}]}'),
('20000000-0000-0000-0000-000000000314', 'fill_blank', 7, '{"sentence": "The findings were ___ across all three experiments.", "options": ["consistent", "subjective", "previous"], "correct": "consistent", "translation": "Os resultados foram consistentes em todos os três experimentos."}'),
('20000000-0000-0000-0000-000000000314', 'fill_blank', 8, '{"sentence": "There was a ___ difference between the two groups.", "options": ["substantial", "valid", "objective"], "correct": "substantial", "translation": "Havia uma diferença substancial entre os dois grupos."}'),
('20000000-0000-0000-0000-000000000314', 'word_order', 9, '{"words": ["The", "results", "showed", "a", "significant", "increase", "in", "performance"], "correct_sentence": "The results showed a significant increase in performance", "translation": "Os resultados mostraram um aumento significativo no desempenho"}'),
('20000000-0000-0000-0000-000000000314', 'word_order', 10, '{"words": ["Personal", "opinions", "can", "be", "quite", "subjective"], "correct_sentence": "Personal opinions can be quite subjective", "translation": "Opiniões pessoais podem ser bem subjetivas"}'),
('20000000-0000-0000-0000-000000000314', 'reading', 11, '{"passage": "Academic writing values precise adjectives. A significant result is one that matters statistically, while a valid argument is logically sound. Good research tries to stay objective rather than subjective, and strong studies show consistent, substantial results across different tests.", "translation": "A escrita acadêmica valoriza adjetivos precisos. Um resultado significant é aquele que importa estatisticamente, enquanto um argumento valid é logicamente sólido. Uma boa pesquisa tenta se manter objective em vez de subjective, e estudos fortes mostram resultados consistent e substantial em diferentes testes.", "question": "What does a valid argument mean, according to the text?", "options": ["One that is subjective", "One that is logically sound", "One that is statistically significant"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000314', 'listening', 12, '{"audio_text": "The results showed a significant increase in performance. This is a valid point that deserves further discussion. The findings were consistent across all three experiments.", "question": "What increased significantly, according to the audio?", "options": ["The cost", "Performance", "The number of experiments"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000314', 'dictation', 13, '{"audio_text": "The findings were consistent across all three experiments.", "expected": "The findings were consistent across all three experiments."}'),
('20000000-0000-0000-0000-000000000314', 'typing', 14, '{"prompt_pt": "Traduza: ''O aumento foi significativo, mas os critérios usados eram um pouco subjetivos.''", "expected": "The increase was significant, but the criteria used were a bit subjective.", "ai_review": true}'),

